-- ============================================================
-- قاعدة بيانات مشروع شركة المثلث كلين للنظافة العامة
-- الترميز: utf8mb4_unicode_ci لدعم اللغة العربية والرموز التعبيرية
-- ============================================================

SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

-- ------------------------------------------------------------
-- جدول settings
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (`setting_key` VARCHAR(100) NOT NULL PRIMARY KEY, `setting_value` TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول admins
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `admins`;
CREATE TABLE `admins` (`id` INT AUTO_INCREMENT PRIMARY KEY, `username` VARCHAR(50) NOT NULL UNIQUE, `password` VARCHAR(255) NOT NULL, `email` VARCHAR(100) NOT NULL, `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول sections_content
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `sections_content`;
CREATE TABLE `sections_content` (`section_key` VARCHAR(50) NOT NULL PRIMARY KEY, `content_data` LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول services
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (`id` INT AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(255) NOT NULL, `icon` VARCHAR(100) NOT NULL, `description` TEXT NOT NULL, `features` TEXT NOT NULL, `sort_order` INT DEFAULT 0, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول why_us
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `why_us`;
CREATE TABLE `why_us` (`id` INT AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(255) NOT NULL, `icon` VARCHAR(100) NOT NULL, `description` TEXT NOT NULL, `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول fleet
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `fleet`;
CREATE TABLE `fleet` (`id` INT AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(255) NOT NULL, `badge` VARCHAR(100) NOT NULL, `image` VARCHAR(255) NOT NULL, `description` TEXT NOT NULL, `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول gallery
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `gallery`;
CREATE TABLE `gallery` (`id` INT AUTO_INCREMENT PRIMARY KEY, `image` VARCHAR(255) NOT NULL, `caption` VARCHAR(255) NOT NULL, `category` VARCHAR(100) DEFAULT 'تنظيف منازل', `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول packages
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `packages`;
CREATE TABLE `packages` (`id` INT AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(255) NOT NULL, `subtitle` VARCHAR(255) NOT NULL, `price_badge` VARCHAR(100) NOT NULL, `price_text` VARCHAR(100) NOT NULL, `features` TEXT NOT NULL, `btn_text` VARCHAR(100) NOT NULL, `btn_link` VARCHAR(255) NOT NULL, `is_popular` TINYINT(1) DEFAULT 0, `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول work_steps
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `work_steps`;
CREATE TABLE `work_steps` (`id` INT AUTO_INCREMENT PRIMARY KEY, `step_number` INT NOT NULL, `title` VARCHAR(255) NOT NULL, `description` TEXT NOT NULL, `color_code` VARCHAR(50) DEFAULT '#0284C7') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول guarantees
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `guarantees`;
CREATE TABLE `guarantees` (`id` INT AUTO_INCREMENT PRIMARY KEY, `icon` VARCHAR(100) NOT NULL, `title` VARCHAR(255) NOT NULL, `description` TEXT NOT NULL, `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول testimonials
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `testimonials`;
CREATE TABLE `testimonials` (`id` INT AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(100) NOT NULL, `location` VARCHAR(100) NOT NULL, `rating` INT DEFAULT 5, `comment` TEXT NOT NULL, `avatar_letter` VARCHAR(10) NOT NULL, `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول faqs
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `faqs`;
CREATE TABLE `faqs` (`id` INT AUTO_INCREMENT PRIMARY KEY, `question` TEXT NOT NULL, `answer` TEXT NOT NULL, `icon` VARCHAR(100) DEFAULT 'fas fa-question-circle', `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول seo_articles
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `seo_articles`;
CREATE TABLE `seo_articles` (`id` INT AUTO_INCREMENT PRIMARY KEY, `icon` VARCHAR(100) NOT NULL, `title` VARCHAR(255) NOT NULL, `description` TEXT NOT NULL, `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول service_areas
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `service_areas`;
CREATE TABLE `service_areas` (`id` INT AUTO_INCREMENT PRIMARY KEY, `category` VARCHAR(100) NOT NULL, `area_name` VARCHAR(100) NOT NULL, `sort_order` INT DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ------------------------------------------------------------
-- جدول bookings
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `bookings`;
CREATE TABLE `bookings` (`id` INT AUTO_INCREMENT PRIMARY KEY, `client_name` VARCHAR(100) NOT NULL, `phone` VARCHAR(30) NOT NULL, `service_type` VARCHAR(100) NULL, `moving_date` DATE NULL, `from_area` VARCHAR(100) NULL, `to_area` VARCHAR(100) NULL, `details` TEXT NULL, `status` ENUM('new','contacted','completed') DEFAULT 'new', `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


